// ================== الإعدادات: عدّل هنا ==================
const CONFIG = {
  teacher_chat_id: '1947443555',  // رقم الـ chat id بتاعك على تليجرام (مش رقم الموبايل)
  grade_model: 'gemini-3.8-flash' // الموديل اللي بيصحح الواجبات
};
// ==========================================================
const j = $input.first().json;
const cb = j.callback_query || null;
const m = cb ? (cb.message || {}) : (j.message || {});
const from = cb ? (cb.from || {}) : (m.from || {});
const text = cb ? '' : (m.text || '').trim();
const caption = (m.caption || '').trim();
const OK_MIME = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const norm = s => String(s || '').replace(/[ً-ْـ]/g, '').replace(/\s+/g, ' ').trim();
const WEAK = 'اعرضلي نقط ضعفي من الواجبات واقترح عليا تدريب عليها';
const HW_HOWTO = 'صوّر ورقة الواجب كويس وابعتها هنا 📷 (صورة أو PDF)\nولو عايز تحدد الواجب، اكتب كوده في الكابشن، مثلاً: HW3';

// أزرار تحت الرسايل (callback_data ← الطلب اللي بيروح للبوت)
const BUTTONS = {
  'ask:simpler': 'اشرحلي آخر إجابة بطريقة أبسط وبمثال من الحياة',
  'ask:example': 'اديني مثال تاني على نفس النقطة اللي فاتت',
  'ask:chart': 'ارسملي رسم بياني يوضح نفس الفكرة اللي فاتت',
  'ask:quiz': 'اديني 5 أسئلة اختيار من متعدد على نفس النقطة اللي فاتت',
  'hw:explain': 'اشرحلي الأفكار اللي غلطت فيها في الواجبات، فكرة فكرة وبشكل مبسط',
  'hw:practice': WEAK
};

// أزرار القائمة الثابتة (بتوصل كنص عادي)
const MENU = {
  [norm('اسأل سؤال')]: { direct: 'اكتب سؤالك في أي حاجة في المنهج ✍️' },
  [norm('اختبرني')]: { kind: 'app' },
  [norm('صحّح واجبي')]: { kind: 'hwlist' },
  [norm('واجباتي')]: { kind: 'hwlist' },
  [norm('الواجب')]: { kind: 'hwlist' },
  [norm('نقط ضعفي')]: { msg: WEAK },
  [norm('اطلب رسم')]: { direct: 'قولي عايز رسم بياني لإيه 📈\nمثلاً: "ارسملي العلاقة بين الضغط والحجم لغاز"' },
  [norm('مساعدة')]: { kind: 'start' }
};

let kind = 'text', file_id = null, mime = null, msg = text, direct_text = '';

if (cb) {
  const data = String(cb.data || '');
  if (BUTTONS[data]) msg = BUTTONS[data];
  else { kind = 'direct'; direct_text = 'الزرار ده قديم 🙏 استخدم الأزرار اللي تحت.'; }
} else if (m.photo && m.photo.length) {
  kind = 'file'; file_id = m.photo[m.photo.length - 1].file_id; mime = 'image/jpeg';
} else if (m.document) {
  if (OK_MIME.includes(m.document.mime_type)) {
    kind = 'file'; file_id = m.document.file_id; mime = m.document.mime_type;
  } else kind = 'unsupported';
} else if (!text) {
  kind = 'unsupported';
} else if (/^\/(start|help|menu)/i.test(text)) {
  kind = 'start';
} else if (/^\/weak/i.test(text)) {
  msg = WEAK;
} else if (/^\/(quiz|app)/i.test(text)) {
  kind = 'app';
} else if (/^\/homework/i.test(text)) {
  kind = 'hwlist';
} else {
  const hit = MENU[norm(text)];
  if (hit) {
    if (hit.kind) kind = hit.kind;
    if (hit.msg) msg = hit.msg;
    if (hit.direct) { kind = 'direct'; direct_text = hit.direct; }
  }
}

return [{ json: {
  ...CONFIG,
  chat_id: m.chat ? m.chat.id : null,
  user_id: from.id || null,
  first_name: from.first_name || '',
  text: msg,
  hw_code: (caption.split(/\s+/)[0] || '').toUpperCase(),
  kind, file_id, mime, direct_text,
  is_callback: !!cb,
  callback_id: cb ? cb.id : null
}}];

const BOT = 'Adaptive Learning Bot';
const USAGE = `أنا ${BOT}، مساعدك الذكي في الكيمياء والعلوم 🧪

استخدم الأزرار اللي تحت 👇
• اسأل سؤال: اسألني في أي حاجة في المنهج
• اختبرني: اختبار تفاعلي بيتصحح فورًا
• صحّح واجبي: ابعت صورة أو PDF للواجب
• نقط ضعفي: تدريب على الأفكار اللي بتغلط فيها
• اطلب رسم: رسم بياني يوضح الفكرة

ومن زرار "المنصة" جنب خانة الكتابة تقدر تشوف مستواك وتتدرّب 🚀`;
const ASK_CODE = `أهلاً بيك في ${BOT} 👋\nمساعدك الذكي في الكيمياء والعلوم مع مستر محمد حسين.\n\nعشان تبدأ، ابعت الكود اللي أخدته من المستر 🔑`;
const APP_TEXT = 'الاختبار التفاعلي جاهز 🚀\nأسئلة من المنهج على قد مستواك، بتتصحح فورًا، والأفكار اللي بتغلط فيها بتتسجل عشان نتدرب عليها.\n\nدوس على الزرار 👇';
const p = $('Prepare').first().json;
const s = $input.first().json || {};
const registered = !!(s.code && s.telegram_id && s.active !== false);
// route: 0 = رد مباشر | 1 = محاولة تسجيل بكود | 2 = تصحيح واجب | 3 = سؤال للبوت | 4 = عرض الواجبات المفتوحة
// menu: true = ابعت الرد ومعاه كيبورد القائمة | app: true = ابعت زرار فتح المنصة
let route = 0, reply_text = '', menu = false, app = false;
const resentOwnCode = registered && p.kind === 'text' && !p.is_callback && String(s.code || '').trim().toUpperCase() === String(p.text || '').trim().toUpperCase();

if (p.kind === 'start') {
  if (registered) { reply_text = `أهلاً يا ${s.name} 👋\n\n${USAGE}`; menu = true; }
  else reply_text = ASK_CODE;
} else if (resentOwnCode) {
  reply_text = `إنت مسجل بالفعل يا ${s.name} ✅\n\n${USAGE}`; menu = true;
} else if (!registered) {
  if (p.kind === 'text' && !p.is_callback) route = 1;
  else reply_text = 'لازم تسجل الأول 🙏 ابعت الكود اللي أخدته من المستر.';
} else if (p.kind === 'app') {
  reply_text = APP_TEXT; app = true;
} else if (p.kind === 'hwlist') {
  route = 4;
} else if (p.kind === 'direct') {
  reply_text = p.direct_text; menu = true;
} else if (p.kind === 'file') {
  route = 2;
} else if (p.kind === 'unsupported') {
  reply_text = 'أنا بستقبل رسايل مكتوبة، أو صورة / PDF للواجب بس 🙏'; menu = true;
} else {
  route = 3;
}

return [{ json: { ...p, registered, student_name: s.name || p.first_name, route, reply_text, menu, app } }];

