return $('Parse Grade').all().map(i => {
  let n = 0;
  try { n = JSON.parse(i.json.mistakes_json || '[]').length; } catch (e) {}
  return { json: { chat_id: i.json.chat_id, reply_text: i.json.reply_text, has_mistakes: i.json.status === 'graded' && n > 0 } };
});

// Node «Homework Cards». The open homework, newest first: one picture per homework with how to send the answer.
const p = $('Merge Student').first().json;
const list = $input.all().map((i) => i.json).filter((h) => h && h.code);
if (!list.length) return [{ json: { chat_id: p.chat_id, kind: 'text', reply_text: 'مفيش واجب مفتوح دلوقتي 📭 لما المستر ينزل واجب جديد هيظهرلك هنا.', menu: true } }];
const items = list.map((h) => {
  const cap = '📝 ' + h.code + ' · ' + (h.title || '') + '\nالدرجة: ' + Number(h.total_marks || 0) + '\n\nحل على ورقة، صوّرها وابعتها هنا واكتب في الكابشن: ' + h.code;
  return h.image_url
    ? { json: { chat_id: p.chat_id, kind: 'photo', url: h.image_url, caption: cap.slice(0, 1000) } }
    : { json: { chat_id: p.chat_id, kind: 'text', reply_text: cap + '\n\n' + String(h.questions || '').slice(0, 3000), menu: false } };
});
items.push({ json: { chat_id: p.chat_id, kind: 'text', reply_text: 'دول الواجبات المفتوحة (' + list.length + ') ✍️\nابعت صورة الحل أو PDF، واكتب كود الواجب في الكابشن (مثلاً ' + list[0].code + ')، وهصححهولك على طول.', menu: true } });
return items;
